+  return new Promise((resolve) => {
+    const port = options.porta !== undefined ? options.porta : 3000;
+    const server = app.listen(port, () => {
+      const actualPort = server.address().port;
+      resolve({
+        porta: actualPort,
+        fechar: () => new Promise((res) => server.close(res))
+      });
